<script>
    (function() {
        // --- 核心：确保 DOM 元素存在 ---
        const app = document.getElementById('majo-status-app');
        if (!app) return; // 安全检查

        // --- 翻页逻辑 ---
        const pages = app.querySelectorAll('.majo-page');
        const dots = app.querySelectorAll('.majo-page-dot');
        const prevBtn = app.querySelector('.majo-prev-btn');
        const nextBtn = app.querySelector('.majo-next-btn');
        let currentPage = 0;
        const totalPages = pages.length;

        function updatePage() {
            pages.forEach((p, i) => {
                p.style.display = (i === currentPage) ? 'flex' : 'none';
            });
            dots.forEach((d, i) => {
                if(i === currentPage) d.classList.add('active');
                else d.classList.remove('active');
            });
        }

        prevBtn.addEventListener('click', (e) => {
            e.preventDefault();
            if (currentPage > 0) { currentPage--; updatePage(); }
        });

        nextBtn.addEventListener('click', (e) => {
            e.preventDefault();
            if (currentPage < totalPages - 1) { currentPage++; updatePage(); }
        });

        // 初始化
        updatePage();


        // --- 处刑按钮逻辑 ---
        const execBtn = app.querySelector('#execution-btn-wrapper');
        const bloodRect = app.querySelector('#blood-rect');
        const checkMark = app.querySelector('#check-mark');
        const textNode = app.querySelector('#main-text');
        const mainGroup = app.querySelector('#main-group');
        const warningText = app.querySelector('.warning-text');

        let isExecuted = false;
        let startTime = 0;
        let animId = null;
        const HOLD_TIME = 2000;

        function frame() {
            if (isExecuted) return;
            const now = Date.now();
            const progress = Math.min((now - startTime) / HOLD_TIME, 1);

            bloodRect.setAttribute('y', 100 - (progress * 100));
            bloodRect.setAttribute('height', progress * 100);

            if (progress >= 1) {
                doExecute();
            } else {
                animId = requestAnimationFrame(frame);
            }
        }

        function start(e) {
            if (isExecuted) return;
            // 触摸屏阻止滚动
            if(e.type === 'touchstart' && e.cancelable) e.preventDefault();

            startTime = Date.now();
            execBtn.classList.add('shaking');
            cancelAnimationFrame(animId);
            animId = requestAnimationFrame(frame);
        }

        function end() {
            if (isExecuted) return;
            cancelAnimationFrame(animId);
            execBtn.classList.remove('shaking');

            // 回退效果
            bloodRect.style.transition = 'all 0.2s';
            bloodRect.setAttribute('y', 100);
            bloodRect.setAttribute('height', 0);
            setTimeout(() => bloodRect.style.transition = 'none', 200);
        }

        function doExecute() {
            isExecuted = true;
            cancelAnimationFrame(animId);
            execBtn.classList.remove('shaking');

            // 锁定状态
            bloodRect.setAttribute('y', 0); bloodRect.setAttribute('height', 100);
            textNode.style.opacity = '0';
            checkMark.style.opacity = '1'; checkMark.style.transform = 'scale(1)';
            mainGroup.style.filter = 'drop-shadow(0 0 15px #ff0000)';
            warningText.innerHTML = "指令已发送<br>EXECUTED";
            warningText.style.color = "#8b0000"; warningText.style.fontWeight = "bold";

            // 发送指令 (穿透查找)
            let targetDoc = document;
            try { if(window.parent) targetDoc = window.parent.document; } catch(e){}

            const ta = targetDoc.querySelector('#send_textarea');
            const btn = targetDoc.querySelector('#send_but');
            if(ta && btn) {
                ta.value = "<request: The verdict has been reached, and the execution procedure is underway.>";
                ta.dispatchEvent(new Event('input', {bubbles:true}));
                setTimeout(() => btn.click(), 50);
            }
        }

        // 绑定事件
        execBtn.addEventListener('mousedown', start);
        window.addEventListener('mouseup', end);
        execBtn.addEventListener('touchstart', start);
        window.addEventListener('touchend', end);

    })();
